  }

  function finalHTML() {
    const lead = "&lt;span class='sbx-lead'&gt;" + P + sup("t+1") + "\u2009y" + sub(MIN + "1") + "&lt;/span&gt;";
    const tail =
      "&lt;span class='sbx-old'&gt;" + P + sup("t") + "\u2009" + eT("0") + "&lt;/span&gt; + " +
      "&lt;span class='sbx-old'&gt;" + CD + "&lt;/span&gt; + " +
      "&lt;span class='sbx-old'&gt;" + P + "\u2009" + eT(idx(1)) + "&lt;/span&gt; + " +
      "&lt;span class='sbx-old'&gt;" + eT("t") + "&lt;/span&gt;";
    return "y" + sub("t") + " = " + lead + " + " + tail;
  }

  function ruleHTML(s) {
    if (s &gt;= FINAL) return "&hellip; keep going until the index reaches " + MIN + "1.";
    return "Same equation, one period earlier: &nbsp; " +
      yT(idx(s + 1)) + " = " + P + "\u2009" + yT(idx(s + 2)) + " + " + eT(idx(s + 1));
  }

  const captions = [];
  captions[0] = "Start from the model: " + yT("t") + " depends on " + yT(idx(1)) + " and the shock " + eT("t") + ".";
  for (let s = 1; s &lt;= M; s++)
    captions[s] = "Reuse the identical equation one step back: one more shock drops out, the power of " + P + " grows by one.";
  captions[FINAL] = "After t+1 substitutions the chain reaches " + yT(MIN + "1") + ": a transient plus every past shock.";

  const ticks = [MIN+"1", CD, "t"+MIN+"4", "t"+MIN+"3", "t"+MIN+"2", "t"+MIN+"1", "t"];
  const nT = ticks.length;
  const tw = 600, th = 76, xL = 44, xR = tw - 24, baseY = 44;
  const tx = i =&gt; xL + (xR - xL) * i / (nT - 1);
  // index along the OLD ordering (0 = t, 1 = t-1, ...) mapped to the flipped axis
  const pos = k =&gt; nT - 1 - k;                 // k=0 (t) -&gt; rightmost, growing k -&gt; left
  const pointerTick = s =&gt; s &gt;= FINAL ? 0 : pos(s + 1);
  const shockTicks = s =&gt; {
    const set = new Set();
    if (s &gt;= FINAL) [0,1,2,3,4].forEach(k =&gt; set.add(pos(k)));
    else for (let k = 0; k &lt;= s; k++) set.add(pos(k));
    return set;
  };

  const wrap = d3.create("div").style("font-family", "system-ui, sans-serif");
  wrap.append("style").html(
    ".sbx-eq{font-family:Georgia,serif;font-size:22px;margin:10px 0 4px;line-height:1.6;}" +
    ".sbx-eq sub{font-size:.7em;}.sbx-eq sup{font-size:.7em;}" +
    ".sbx-lead{background:#fff3d1;border:1px solid #f0a202;border-radius:5px;padding:1px 5px;}" +
    ".sbx-flash{color:#e45756;font-weight:bold;}.sbx-old{color:#333;}" +
    ".sbx-rule{font-family:Georgia,serif;font-size:15px;color:#666;min-height:20px;}" +
    ".sbx-rule sub{font-size:.72em;}.sbx-cap{font-size:13px;color:#333;margin-top:4px;}"
  );

  const ctr = wrap.append("div").style("display","flex").style("gap","6px").style("margin-bottom","4px");
  const mk = t =&gt; ctr.append("button").text(t)
    .style("padding","3px 10px").style("font-size","13px").style("border","1px solid #ccc")
    .style("border-radius","6px").style("background","#fff").style("cursor","pointer");
  const bPlay = mk("Pause"), bReset = mk("Reset"), bPrev = mk("\u2039"), bNext = mk("\u203A");

  const ruleDiv = wrap.append("div").attr("class","sbx-rule");
  const eqDiv   = wrap.append("div").attr("class","sbx-eq");
  const tlHolder = wrap.append("div");
  const capDiv  = wrap.append("div").attr("class","sbx-cap");

  let f = 0, playing = true;

  function drawTimeline(s) {
    tlHolder.selectAll("*").remove();
    const svg = tlHolder.append("svg").attr("viewBox",[0,0,tw,th]).attr("width",tw)
      .attr("style","max-width:100%;height:auto;");
    svg.append("line").attr("x1",xL-10).attr("x2",xR+10).attr("y1",baseY).attr("y2",baseY).attr("stroke","#ddd");
    const sh = shockTicks(s), ptr = pointerTick(s);
    svg.append("text").attr("x",xL-16).attr("y",baseY-12).attr("font-size",12).attr("fill","#e45756").text(E);
    ticks.forEach((lab,i) =&gt; {
      svg.append("line").attr("x1",tx(i)).attr("x2",tx(i)).attr("y1",baseY-4).attr("y2",baseY+4).attr("stroke","#bbb");
      svg.append("text").attr("x",tx(i)).attr("y",baseY+20).attr("text-anchor","middle").attr("font-size",12).attr("fill","#888").text(lab);
      if (sh.has(i)) svg.append("circle").attr("cx",tx(i)).attr("cy",baseY-14).attr("r",5).attr("fill","#e45756").attr("opacity",0.85);
    });
    svg.append("circle").attr("cx",tx(ptr)).attr("cy",baseY).attr("r",11).attr("fill","#4c78a8").attr("stroke","#2f5c8f").attr("stroke-width",2);
    svg.append("text").attr("x",tx(ptr)).attr("y",baseY+4).attr("text-anchor","middle").attr("font-size",11).attr("fill","#fff").attr("font-weight","bold").text("y");
  }

  function update() {
    ruleDiv.html(ruleHTML(f));
    eqDiv.html(f &gt;= FINAL ? finalHTML() : resultHTML(f));
    capDiv.html(captions[Math.min(f, FINAL)]);
    drawTimeline(f);
  }

  bPlay.on("click", () =&gt; { playing = !playing; bPlay.text(playing ? "Pause" : "Play"); });
  bReset.on("click", () =&gt; { f = 0; update(); });
  bPrev.on("click", () =&gt; { playing = false; bPlay.text("Play"); f = (f - 1 + total) % total; update(); });
  bNext.on("click", () =&gt; { playing = false; bPlay.text("Play"); f = (f + 1) % total; update(); });

  const timer = setInterval(() =&gt; { if (playing) { f = (f + 1) % total; update(); } }, 1500);
  invalidation.then(() =&gt; clearInterval(timer));

  update();
  return wrap.node();
}






Collecting the terms gives the general solution:
\[
y_t = \phi^{\,t+1} y_{-1} + \sum_{i=0}^{t} \phi^{\,i}\, w_{t-i}
= \phi^{\,t+1} y_{-1} + w_t + \phi\, w_{t-1} + \cdots + \phi^{\,t} w_0
\tag{4.3}\]
The value of \(y_t\) splits into two pieces: the initial condition \(\phi^{\,t+1} y_{-1}\), and a weighted sum of every shock since the start, with weight \(\phi^{\,i}\) on the shock \(i\) periods ago.


4.2.2 The dynamic multiplier and impulse response function
Since Equation 4.3 writes \(y_t\) as a linear function of the shocks, the effect of a single shock can be read off directly. This is the key result obtained by rewriting the process through recursive substitution.
Restarting the count at an arbitrary date \(t\), following the same logic applied above:
\[
y_{t+j} = \phi^{\,j+1} y_{t-1} + \sum_{i=0}^{j}\phi^{\,i}\, w_{t+j-i}
\tag{4.4}\]
and differentiating with respect to the shock \(w_t\):
\[
\frac{\partial\, y_{t+j}}{\partial\, w_t} = \phi^{\,j}
\tag{4.5}\]
This defines the dynamic multiplier: the response of \(y\), \(j\) periods ahead, to a one-unit shock today. Two features matter:

It depends only on the horizon \(j\), not on the date \(t\): the system reacts to a shock in the same way no matter when it lands.
This is exactly an impulse-response function, tracing \(\phi^{\,j}\) for \(j = 0, 1, 2, \dots\) draws the system’s response to an impulse.

The shape depends entirely on \(\phi\):

\(0&lt;\phi&lt;1\): monotone geometric decay toward zero;
\(-1&lt;\phi&lt;0\): decay with alternating sign (damped oscillation);
\(\phi&gt;1\): explosive monotone growth;
\(\phi&lt;-1\): explosive oscillation.

The dividing line is \(|\phi|&lt;1\): inside it a shock’s effect eventually dies out and the system is stable; outside it the effect grows without bound, the process is explosive. The borderline \(\phi=1\) is the random walk, where \(\phi^{\,j}=1\) for every \(j\) and a shock’s effect is permanent.
Move the slider through all four regimes — this is the response \(\partial y_{t+j}/\partial w_t = \phi^{\,j}\):

viewof phi = Inputs.range([-1.2, 1.2], {value: 0.8, step: 0.05, label: "\u03C6"})







{
  const H = 20;
  const data = d3.range(0, H + 1).map(j =&gt; ({j, resp: Math.pow(phi, j)}));
  return Plot.plot({
    height: 300,
    marginLeft: 60,
    x: { label: "horizon j \u2192" },
    y: { label: "\u2191 response to a unit shock", grid: true },
    marks: [
      Plot.ruleY([0]),
      Plot.barY(data, { x: "j", y: "resp",
